sys_script_fix.script:
function _renameProdClassificationTable() {
	var label = gs.getMessage('UNSPSC Classification');
	var plural = gs.getMessage('UNSPSC Classifications');

	var gr = new GlideRecord('sys_db_object');
	gr.addQuery('name', 'samp_sw_product_classification');
	gr.query();
	if (gr.next()) {
		gr.setValue('label', label);
		gr.update();
	}

	var docObj = new GlideRecord('sys_documentation');
	docObj.addQuery('name', 'samp_sw_product_classification');
	docObj.addNullQuery('element');
	docObj.query();
	if (docObj.next()) {
		docObj.setValue('plural', plural);
		docObj.update();
	}
}

_renameProdClassificationTable();
